package com.androidhit.lumadrift.engine;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
public final class GenerateProgressionV2 {
 static final int[] SINGLE={1,2,4,8}, PAIR={3,5,6,9,10,12};
 static class Analysis {
  final Level l;final long[] rays;double[] chance;Map<Integer,Double> sparse;int decisions,unsafe,legalChoices,forced,edges,initialLegal;double probability,score;
  Analysis(Level l){this.l=l;int n=l.tiles.size();rays=new long[n];chance=n<=18?new double[1<<n]:null;sparse=n>18?new HashMap<>():null;if(chance!=null){Arrays.fill(chance,-1);chance[0]=1;}else sparse.put(0,1.0);
   for(Tile t:l.tiles)for(Tile o:l.tiles){int dr=o.row-t.row,dc=o.col-t.col;if(t.id!=o.id&&(t.direction.dr==0?dr==0&&dc*t.direction.dc>0:dc==0&&dr*t.direction.dr>0)){rays[t.id]|=1L<<o.id;edges++;}}
   probability=p(l.allTilesMask,l.initialGateMask);long mask=l.allTilesMask;int gates=l.initialGateMask;
   for(int next:l.solution){int legal=0,bad=0;for(Tile t:l.tiles)if(can(mask,gates,t)){legal++;if(p(mask&~(1L<<t.id),gates^t.switchMask)==0)bad++;}if(mask==l.allTilesMask)initialLegal=legal;if(legal==1)forced++;if(bad>0&&bad<legal)decisions++;unsafe+=bad;legalChoices+=legal;Tile t=l.tile(next);mask&=~(1L<<next);gates^=t.switchMask;}
   int sw=0,pair=0;for(Tile t:l.tiles){if(t.switchMask!=0)sw++;if(Integer.bitCount(t.switchMask)>1)pair++;}
   score=3*n+2*sw+pair+10*-Math.log(Math.max(.0001,probability))+1.5*decisions+.2*edges;chance=null;sparse=null;
  }
  boolean can(long m,int g,Tile t){return(m&(1L<<t.id))!=0&&(g&t.direction.bit)!=0&&(m&rays[t.id])==0;}
  double p(long m,int g){int k=(int)m;Double cached=chance==null?sparse.get(k):chance[k]>=0?chance[k]:null;if(cached!=null)return cached;int count=0;double sum=0;for(Tile t:l.tiles)if(can(m,g,t)){count++;sum+=p(m&~(1L<<t.id),g^t.switchMask);}double value=count==0?0:sum/count;if(chance==null)sparse.put(k,value);else chance[k]=value;return value;}
 }
 static boolean occupied(List<Tile> ts,int r,int c){for(Tile t:ts)if(t.row==r&&t.col==c)return true;return false;}
 static boolean ray(int r,int c,Direction d,Tile t){return d.dr==0?r==t.row&&(t.col-c)*d.dc>0:c==t.col&&(t.row-r)*d.dr>0;}
 static Level candidate(int number,boolean remix,long seed){int chapter=(number-1)/30+1,pos=(number-1)%30;int size=chapter<4?5:chapter<=16?6:7;int n=remix?Math.min(20,11+chapter+pos/10):Math.min(20,9+chapter+pos/10);if(!remix&&chapter>=9)n=17+pos/8;if(chapter==1)n=remix?11+(number-4)/9:8+(number-4)/6;
  int switches=remix?Math.min(8,3+chapter/2):Math.min(9,2+(chapter+1)/2);if(chapter==1)switches=number<=6?2:number<=12?3:remix?4:3;int doubles=remix?Math.max(1,switches-1):0;
  Random rng=new Random(seed);ArrayList<Tile> placed=new ArrayList<>();ArrayList<Integer> ids=new ArrayList<>();for(int i=0;i<n-1;i++)ids.add(i);Collections.shuffle(ids,rng);int[] types=new int[n];for(int i=0;i<switches;i++)types[ids.get(i)]=i<doubles?2:1;
  int gates=15;for(int id=n-1;id>=0;id--){Tile best=null;int bestPre=0;double bestScore=-1;for(int sample=0;sample<150;sample++){int mask=types[id]==0?0:types[id]==1?SINGLE[rng.nextInt(4)]:PAIR[rng.nextInt(6)];int pre=gates^mask;if(pre==0)continue;int r=rng.nextInt(size),c=rng.nextInt(size);if(occupied(placed,r,c))continue;Direction d=Direction.values()[rng.nextInt(4)];if((pre&d.bit)==0)continue;boolean clear=true;int dependencies=0;for(Tile t:placed){if(ray(r,c,d,t)){clear=false;break;}if(ray(t.row,t.col,t.direction,new Tile(id,r,c,d,mask)))dependencies++;}if(!clear)continue;double score=rng.nextDouble()*8+dependencies*3+(r>0&&r<size-1&&c>0&&c<size-1?1:0);if(score>bestScore){bestScore=score;best=new Tile(id,r,c,d,mask);bestPre=pre;}}if(best==null)return null;placed.add(best);gates=bestPre;}
  placed.sort(Comparator.comparingInt(t->t.id));int[] solution=new int[n];for(int i=0;i<n;i++)solution[i]=i;return new Level(number,chapter,size,gates,placed,solution,false,seed);
 }
 static double target(int number,boolean remix){if(number<=6)return remix?.65:.80;if(!remix&&number>240)return .10*Math.exp(-1.2*(number-240)/760.0);double x=(number-4)/236.0;return remix?.50*Math.exp(-2.1*x):.65*Math.exp(-1.95*x);}
 static String encode(Level l,int margin){StringBuilder s=new StringBuilder().append(l.size).append('|').append(l.initialGateMask).append('|').append(l.seed).append('|').append(margin).append('|');for(Tile t:l.tiles)s.append(t.row).append(',').append(t.col).append(',').append(t.direction.ordinal()).append(',').append(t.switchMask).append(';');return s.toString();}
 public static void main(String[] args)throws Exception{Path folder=Paths.get(args[0]);Files.createDirectories(folder);StringBuilder java=new StringBuilder("package com.androidhit.lumadrift.engine;\n\n/** Frozen, independently identified G/H progression. Generated offline; never regenerated on a phone. */\nfinal class ProgressionV2Layouts {\n    private ProgressionV2Layouts() { }\n");StringBuilder csv=new StringBuilder("family,number,pieces,initial_legal,choice_points,unsafe_path_choices,legal_path_choices,forced_steps,random_legal_exact,structural_score,margin,base\n");
  for(boolean remix:new boolean[]{false,true}){int total=remix?240:1000;ArrayList<Analysis> selected=new ArrayList<>();for(int number=1;number<=total;number++){Analysis best=null;double loss=Double.POSITIVE_INFINITY;if(number<=3)best=new Analysis(remix?LevelCatalog.remix(number):LevelCatalog.get(number));else{int desired=number<=12?1:number<=60?2:number<=120?3:4;for(int attempt=0;attempt<55;attempt++){long seed=(remix?0x484152444D49584CL:0x4741544544524946L)^((long)number*0x9E3779B97F4A7C15L)^((long)attempt*0x632BE59BD9B4E019L);Level l=candidate(number,remix,seed);if(l==null)continue;Analysis a=new Analysis(l);double d=Math.abs(Math.log(Math.max(.0001,a.probability)/target(number,remix)))+Math.max(0,desired-a.decisions)*1.2+(a.initialLegal<2?1.8:0)+(a.initialLegal>5?.7:0);if(a.probability==0||a.decisions==0)d+=100;if(d<loss){loss=d;best=a;}if(loss<.12)break;}}if(best==null)throw new AssertionError("No candidate "+number);selected.add(best);if(number%30==0)System.out.println((remix?"Remix":"Journey")+" selected "+number);}
   for(int ch=0;ch<(total+29)/30;ch++){int first=ch==0?3:ch*30;selected.subList(first,Math.min(total,(ch+1)*30)).sort(Comparator.comparingDouble(a->a.score));}
   java.append("    static final String[] ").append(remix?"REMIX":"JOURNEY").append(" = {\n");for(int i=0;i<total;i++){Analysis a=selected.get(i);int margin=i<3?4:a.decisions>=6||a.probability<.12&&a.decisions>=4?3:2;if(i<6)margin=Math.max(3,margin);java.append("        \"").append(encode(a.l,margin)).append("\"").append(i==total-1?"\n":",\n");csv.append(remix?"remix":"journey").append(',').append(i+1).append(',').append(a.l.tiles.size()).append(',').append(a.initialLegal).append(',').append(a.decisions).append(',').append(a.unsafe).append(',').append(a.legalChoices).append(',').append(a.forced).append(',').append(a.probability).append(',').append(a.score).append(',').append(margin).append(',').append(a.l.tiles.size()+margin).append('\n');}java.append("    };\n");}
 java.append("}\n");Files.write(folder.resolve("ProgressionV2Layouts.java"),java.toString().getBytes(StandardCharsets.UTF_8));Files.write(folder.resolve("progression-v2-selection.csv"),csv.toString().getBytes(StandardCharsets.UTF_8));}
}
